def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        # 交换相邻位置的元素, i为需要更改的索引
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

